from selenium.webdriver.common.by import By
from taf.selenium.sc.common.exceptions import ParamValueError
from taf.selenium.sc.common.common import LocalBasicPage


class Menu(LocalBasicPage):
    """
    The class manages which menu tab will be clicked
    """
    LOGO_XPATH = '//div[@class="app-name ng-binding"]'
    MENU_LENGTH_WITH_ONE = 1
    MENU_LENGTH_WITH_TWO = 2
    FIRST_MENU_INDEX = 0
    SECOND_MENU_INDEX = 1
    _MAIN_MENU_XPATH = '//*[contains(@href, "{}")]'
    _TARGET_TAB_XPATH = '//*[contains(text(), "{}")]/parent::li'

    def __init__(self, driver):
        self._driver = driver
        super(Menu, self).__init__(driver)

    def open_page(self, menu_list):
        """
        Open a new page of selenium_sbts web, if target page has been opened, it won't be opened again
        :param menu_list: the menu list of selenium_sbts's page
        """
        if len(menu_list) == self.MENU_LENGTH_WITH_ONE:
            self.click_enabled_element_after_visible(
                (By.XPATH, self._MAIN_MENU_XPATH.format(menu_list[self.FIRST_MENU_INDEX]))
            )
            return

        if not menu_list:
            raise ParamValueError("menu list is empty")

        menu_xpath_list = [self._MAIN_MENU_XPATH.format(menu_list[self.FIRST_MENU_INDEX]),
                           self._TARGET_TAB_XPATH.format(menu_list[self.SECOND_MENU_INDEX])]

        if self._is_page_active(menu_list):
            return

        for index, xpath in enumerate(menu_xpath_list):
            self.click_enabled_element_after_visible((By.XPATH, xpath))

    def _is_page_active(self, menu_list):
        is_active = 'active' in (self.get_attribute_by_xpath(
            self._TARGET_TAB_XPATH.format(menu_list[self.SECOND_MENU_INDEX]), 'class'))

        if len(menu_list) == self.MENU_LENGTH_WITH_TWO and is_active:
            return True

        return False
